# TCP/IP Server in C

Here's a complete TCP server implementation in C with explanations:

## Basic TCP Server

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len;
    char buffer[BUFFER_SIZE];
    int opt = 1;

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set socket options to reuse address
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt))) {
        perror("setsockopt failed");
        exit(EXIT_FAILURE);
    }

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;  // Accept connections on any interface
    server_addr.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        exit(EXIT_FAILURE);
    }

    // Listen for connections
    if (listen(server_fd, 10) < 0) {
        perror("Listen failed");
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d...\n", PORT);

    // Accept client connections
    client_len = sizeof(client_addr);
    client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
    if (client_fd < 0) {
        perror("Accept failed");
        exit(EXIT_FAILURE);
    }

    printf("Client connected: %s:%d\n", 
           inet_ntoa(client_addr.sin_addr), 
           ntohs(client_addr.sin_port));

    // Communication loop
    while (1) {
        memset(buffer, 0, BUFFER_SIZE);

        // Receive data from client
        int bytes_read = read(client_fd, buffer, BUFFER_SIZE);
        if (bytes_read <= 0) {
            printf("Client disconnected\n");
            break;
        }

        printf("Received: %s\n", buffer);

        // Send response to client
        char response[] = "Message received by server";
        write(client_fd, response, strlen(response));
    }

    // Close sockets
    close(client_fd);
    close(server_fd);

    return 0;
}
```

## Multi-Client Server (Using Fork)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <sys/wait.h>
#include <signal.h>

#define PORT 8080
#define BUFFER_SIZE 1024

// Handle zombie processes
void sigchld_handler(int sig) {
    while (waitpid(-1, NULL, WNOHANG) > 0);
}

void handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];

    while (1) {
        memset(buffer, 0, BUFFER_SIZE);

        int bytes_read = read(client_fd, buffer, BUFFER_SIZE);
        if (bytes_read <= 0) {
            break;
        }

        printf("Received: %s\n", buffer);

        // Echo back to client
        write(client_fd, buffer, bytes_read);
    }

    close(client_fd);
    printf("Client disconnected\n");
}

int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len;
    int opt = 1;

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set socket options
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt))) {
        perror("setsockopt failed");
        exit(EXIT_FAILURE);
    }

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind
    if (bind(server_fd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        exit(EXIT_FAILURE);
    }

    // Listen
    if (listen(server_fd, 10) < 0) {
        perror("Listen failed");
        exit(EXIT_FAILURE);
    }

    // Handle SIGCHLD to reap zombie processes
    signal(SIGCHLD, sigchld_handler);

    printf("Server listening on port %d...\n", PORT);

    // Accept multiple clients
    while (1) {
        client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);

        if (client_fd < 0) {
            perror("Accept failed");
            continue;
        }

        printf("New client connected: %s:%d\n", 
               inet_ntoa(client_addr.sin_addr), 
               ntohs(client_addr.sin_port));

        // Fork to handle client
        if (fork() == 0) {
            close(server_fd);  // Child doesn't need server socket
            handle_client(client_fd);
            exit(0);
        }

        close(client_fd);  // Parent doesn't need client socket
    }

    close(server_fd);
    return 0;
}
```

## Compilation and Usage

### Compile the Server
```bash
gcc -o server server.c
```

### Run the Server
```bash
./server
```

### Test with Netcat
```bash
# In another terminal
nc localhost 8080
```

### Test with Telnet
```bash
telnet localhost 8080
```

## Key Functions Explained

| Function | Purpose |
|----------|---------|
| `socket()` | Creates a new socket |
| `setsockopt()` | Sets socket options |
| `bind()` | Binds socket to address/port |
| `listen()` | Marks socket as passive |
| `accept()` | Accepts incoming connection |
| `read()`/`write()` | Send/receive data |
| `close()` | Closes socket |
| `fork()` | Creates child process (multi-client) |

## Important Notes

1. **Error Handling**: Always check return values of system calls
2. **Socket Options**: `SO_REUSEADDR` allows quick restart
3. **Byte Order**: Use `htons()` for port numbers
4. **Security**: Add authentication for production use
5. **Resources**: Always close sockets to prevent leaks

## Simple Client for Testing

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int sock = 0;
    struct sockaddr_in serv_addr;
    char buffer[BUFFER_SIZE] = {0};

    // Create socket
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation error");
        return -1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(PORT);

    // Convert IPv4 addresses from text to binary
    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
        perror("Invalid address");
        return -1;
    }

    // Connect to server
    if (connect(sock, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection failed");
        return -1;
    }

    printf("Connected to server\n");

    // Send message
    send(sock, "Hello from client", strlen("Hello from client"), 0);
    printf("Message sent\n");

    // Receive response
    read(sock, buffer, BUFFER_SIZE);
    printf("Response: %s\n", buffer);

    close(sock);
    return 0;
}
```

This provides a complete TCP server implementation with both single and multi-client support! 😊

